	/** @var array<string,string> */private readonly array $credentialKeys;/** @var array<string,string> */private readonly array $responseKeys;/** @var array<string,string> */private readonly array $syncKeys;private readonly \Closure $replicaResolver;private readonly \Closure $authorizer;private readonly ?\Closure $scopeResolver;private readonly \Closure $clock;
	/** @param array<string,string> $credentialKeys @param array<string,string> $responseKeys @param array<string,string> $syncKeys */
	public function __construct(private readonly PanelDataSourceRegistry $sources,callable $replicaResolver,array $credentialKeys,array $responseKeys,private readonly string $currentResponseKeyId,array $syncKeys,private readonly string $currentSyncKeyId,private readonly PanelLocalFirstReplayStore $replayStore,callable $authorizer,?callable $scopeResolver=null,?callable $clock=null,private readonly int $maximumClockSkewSeconds=300){
		$this->credentialKeys=self::keys($credentialKeys,'credential');$this->responseKeys=self::keys($responseKeys,'response');$this->syncKeys=self::keys($syncKeys,'sync');if(!isset($this->responseKeys[$currentResponseKeyId])||!isset($this->syncKeys[$currentSyncKeyId])){throw new \InvalidArgumentException('Current local-first response or sync key is not trusted.');}if($maximumClockSkewSeconds<0||$maximumClockSkewSeconds>3600){throw new \InvalidArgumentException('Local-first clock skew must be between 0 and 3600 seconds.');}$this->replicaResolver=\Closure::fromCallable($replicaResolver);$this->authorizer=\Closure::fromCallable($authorizer);$this->scopeResolver=$scopeResolver===null?null:\Closure::fromCallable($scopeResolver);$this->clock=$clock===null?static fn():string=>gmdate('c'):\Closure::fromCallable($clock);
