		$ability=$request->kind()==='mutation_batch'?'mutate':'sync';if(!$credential->allows($ability)){throw new \LogicException('Local-first credential does not grant this operation.');}$this->authorize('local_first.'.$ability,['credential_id'=>$credential->credentialId(),'actor_id'=>$credential->actorId(),'tenant_id'=>$credential->tenantId(),'device_id'=>$credential->deviceId(),'request_digest'=>$request->digest(),'sequence'=>$request->sequence()]);
		try{$claim=$this->replayStore->claim($credential->credentialId(),$request->sequence(),$request->digest(),$now);}catch(PanelLocalFirstReplayException $error){return$this->respond($request,'error',['error'=>['code'=>$error->publicCode(),'retryable'=>$error->retryable()]],$now);}if(!$claim->acquiredLease()){$stored=$claim->response();if(!$stored instanceof PanelLocalFirstResponse){throw new \UnexpectedValueException('Local-first replay claim omitted its completed response.');}return$stored;}
		try{[$status,$body]=$request->kind()==='mutation_batch'?$this->mutate($request):$this->synchronize($request);$response=$this->respond($request,$status,$body,$now);$this->replayStore->complete($claim,$response);return$response;}
		catch(PanelDataMutationConflict $error){$this->replayStore->abandon($claim);return$this->respond($request,'conflict',['error'=>['code'=>'mutation_conflict','retryable'=>true,'details'=>$error->jsonSerialize()]],$now);}
