	/** @return array{string,array<string,mixed>} */private function mutate(PanelLocalFirstRequest $request):array{
		$payload=$request->payload();self::shape($payload,['type','version','source','atomic','mutations'],'local-first mutation batch');if(($payload['type']??null)!=='panel_local_first_mutation_batch'||($payload['version']??null)!==1||!is_string($payload['source']??null)||!is_bool($payload['atomic']??null)||!is_array($payload['mutations']??null)||!array_is_list($payload['mutations'])||$payload['mutations']===[]||count($payload['mutations'])>100){throw new \InvalidArgumentException('Local-first mutation batch is invalid.');}$source=PanelOperationsGuard::name($payload['source'],'local-first source');$credential=$request->credential();if(!$credential->allowsSource($source)){throw new \LogicException('Local-first credential does not grant this data source.');}$scope=$this->scope($request);$mutations=[];
		foreach($payload['mutations']as$item){if(!is_array($item)){throw new \InvalidArgumentException('Local-first mutation entry is invalid.');}self::shape($item,['operation','key','values','idempotency_key','metadata','expected_revision','reason','return_record'],'local-first mutation entry');if(!is_string($item['operation']??null)||(!is_string($item['key']??null)&&!is_int($item['key']??null))||!is_array($item['values']??null)||!is_string($item['idempotency_key']??null)||!is_array($item['metadata']??null)||(!is_int($item['expected_revision']??null)&&($item['expected_revision']??null)!==null)||!is_string($item['reason']??null)||!is_bool($item['return_record']??null)){throw new \InvalidArgumentException('Local-first mutation entry is invalid.');}$options=['idempotency_key'=>$item['idempotency_key'],'actor_id'=>$scope['actor_id'],'tenant'=>$scope['tenant'],'authorization'=>$scope['authorization'],'metadata'=>$item['metadata'],'expected_revision'=>$item['expected_revision'],'reason'=>$item['reason'],'return_record'=>$item['return_record']];$mutations[]=PanelDataMutation::make($item['operation'],$item['key'],$item['values'],$options);}
		$result=$this->sources->mutateBatch($source,new PanelDataMutationBatch($mutations,$payload['atomic']));return['ok',['result'=>$result->jsonSerialize()]];
	}

	/** @return array{string,array<string,mixed>} */private function synchronize(PanelLocalFirstRequest $request):array{
		$payload=$request->payload();self::shape($payload,['type','version','changes'],'local-first document batch');if(($payload['type']??null)!=='panel_local_first_document_batch'||($payload['version']??null)!==1||!is_array($payload['changes']??null)||!array_is_list($payload['changes'])||$payload['changes']===[]||count($payload['changes'])>128){throw new \InvalidArgumentException('Local-first document batch is invalid.');}$credential=$request->credential();$replica=($this->replicaResolver)($credential->actorId(),$credential,$request);if(!$replica instanceof PanelLocalReplica){throw new \UnexpectedValueException('Local-first replica resolver returned an invalid replica.');}$branches=[];$ids=[];
		foreach($payload['changes']as$change){if(!is_array($change)){throw new \InvalidArgumentException('Local-first document change is invalid.');}self::shape($change,['document_id','base_clock','operations'],'local-first document change');if(!is_string($change['document_id']??null)||!is_array($change['base_clock']??null)||!is_array($change['operations']??null)||!array_is_list($change['operations'])){throw new \InvalidArgumentException('Local-first document change is invalid.');}$id=PanelOperationsGuard::identifier($change['document_id'],'sync document id');if(isset($ids[$id])){throw new \InvalidArgumentException('Local-first document batches cannot repeat a document.');}$ids[$id]=true;$current=$replica->document($id);$serverClock=$current?->clock()??[];foreach($change['base_clock']as$actor=>$counter){PanelOperationsGuard::identifier((string)$actor,'sync actor id');if(!is_int($counter)||$counter<0||$counter>(int)($serverClock[$actor]??0)){throw new \LogicException('Local-first document base clock is not server-observed.');}}$branches[]=PanelSyncDocument::branch($id,$change['base_clock'],$credential->sourceActor(),$change['operations']);}
		$envelope=PanelSyncEnvelope::sign($credential->sourceActor(),$request->sequence(),$request->issuedAt(),$branches,$this->currentSyncKeyId,$this->syncKeys[$this->currentSyncKeyId]);$merge=$replica->mergeIdempotently($envelope);$documents=[];$conflicts=0;foreach(array_keys($ids)as$id){$document=$replica->document($id);if($document){$documents[]=$document->jsonSerialize();$conflicts+=count($document->conflicts());}}return[$merge['new_conflicts']>0?'conflict':'ok',['merge'=>$merge,'documents'=>$documents,'conflict_count'=>$conflicts]];
	}

	/** @return array{actor_id:string,tenant:?string,authorization:array<string,mixed>} */private function scope(PanelLocalFirstRequest $request):array{$credential=$request->credential();$scope=['actor_id'=>$credential->actorId(),'tenant'=>$credential->tenantId(),'authorization'=>[]];if($this->scopeResolver!==null){try{$resolved=($this->scopeResolver)($credential,$request);}catch(\Throwable $error){throw new \LogicException('Local-first scope resolution failed closed.',0,$error);}if(!is_array($resolved)||array_keys($resolved)!==['actor_id','tenant','authorization']||!is_array($resolved['authorization']??null)){throw new \UnexpectedValueException('Local-first scope resolver returned an invalid scope.');}$scope=$resolved;}if((string)$scope['actor_id']!==$credential->actorId()||$scope['tenant']!==$credential->tenantId()){throw new \LogicException('Local-first scope resolver cannot widen credential identity.');}return['actor_id'=>$credential->actorId(),'tenant'=>$credential->tenantId(),'authorization'=>PanelOperationsGuard::safeMetadata($scope['authorization'])];}
	/** @param array<string,mixed> $body */private function respond(PanelLocalFirstRequest $request,string $status,array $body,string $now):PanelLocalFirstResponse{return PanelLocalFirstResponse::sign($request->digest(),$request->sequence(),$status,$body,$now,$this->currentResponseKeyId,$this->responseKeys[$this->currentResponseKeyId]);}
	/** @param array<string,mixed> $context */private function authorize(string $ability,array $context):void{try{$result=($this->authorizer)($ability,$context,$this);$allowed=$result===true||($result instanceof PanelPolicyDecision&&$result->allowed())||($result instanceof PanelSecurityDecision&&$result->allowed());}catch(\Throwable $error){throw new \LogicException('Local-first gateway authorization failed closed.',0,$error);}if(!$allowed){throw new \LogicException('Local-first gateway operation is not authorized.');}}
	private function now():string{$value=($this->clock)();if(!$value instanceof \DateTimeInterface&&!is_string($value)&&!is_int($value)){throw new \UnexpectedValueException('Local-first gateway clock must return an instant.');}return PanelOperationsGuard::instant($value);}
	/** @param array<string,mixed> $value @param list<string> $keys */private static function shape(array $value,array $keys,string $label):void{$actual=array_keys($value);sort($actual,SORT_STRING);sort($keys,SORT_STRING);if($actual!==$keys){throw new \InvalidArgumentException(ucfirst($label).' shape is invalid.');}}
	/** @param array<string,string> $keys @return array<string,string> */private static function keys(array $keys,string $label):array{if($keys===[]||count($keys)>16){throw new \InvalidArgumentException('Local-first '.$label.' keys are invalid.');}$result=[];foreach($keys as$id=>$key){$id=PanelOperationsGuard::name((string)$id,'local-first '.$label.' key id');if(!is_string($key)||strlen($key)<32){throw new \InvalidArgumentException('Local-first '.$label.' keys require at least 32 bytes.');}$result[$id]=$key;}ksort($result,SORT_STRING);return$result;}
	public function jsonSerialize():array{return PanelManifestContract::stamp(['type'=>'panel_local_first_gateway_manifest','version'=>1,'credential_key_ids'=>array_keys($this->credentialKeys),'response_key_ids'=>array_keys($this->responseKeys),'sync_key_ids'=>array_keys($this->syncKeys),'current_response_key_id'=>$this->currentResponseKeyId,'current_sync_key_id'=>$this->currentSyncKeyId,'maximum_clock_skew_seconds'=>$this->maximumClockSkewSeconds,'default_deny'=>false,'capabilities'=>['device_attestation'=>true,'p256_request_signatures'=>true,'signed_responses'=>true,'exact_replay'=>true,'contiguous_sequences'=>true,'host_projected_scope'=>true,'mutation_plane'=>true,'crdt_operation_batches'=>true,'client_authored_registers_rejected'=>true,'conflict_evidence'=>true,'secret_keys_serialized'=>false]]);}
}
